#[derive(Clone, Debug)]
pub struct SmeltRegExp {
    id: usize,
    source: String,
    flags: String,
    last_index: ::std::rc::Rc<::std::cell::RefCell<usize>>,
}

impl PartialEq for SmeltRegExp { fn eq(&self, other: &Self) -> bool { self.source == other.source && self.flags == other.flags && *self.last_index.borrow() == *other.last_index.borrow() } }

impl SmeltRegExp {
    /// Construct a JavaScript-like RegExp value with shared lastIndex state.
    pub fn new(source: String, flags: String) -> Self {
        Self { id: smelt_next_object_id(), source, flags, last_index: ::std::rc::Rc::new(::std::cell::RefCell::new(0)) }
    }
    /// Return true when this RegExp has a flag.
    pub fn has_flag(&self, flag: char) -> bool {
        self.flags.chars().any(|value| value == flag)
    }
    /// Compile the Rust regex equivalent for this JavaScript RegExp.
    fn compiled(&self) -> fancy_regex::Regex {
        self.try_compiled().expect("regex compile failed")
    }
    /// Try to compile the Rust regex equivalent for this JavaScript RegExp.
    fn try_compiled(&self) -> Option<fancy_regex::Regex> {
        let mut prefix = String::new();
        if self.has_flag('i') { prefix.push('i'); }
        if self.has_flag('m') { prefix.push('m'); }
        if self.has_flag('s') { prefix.push('s'); }
        let translated_source = self.source.replace("[^]", "(?s:.)");
        let pattern = if prefix.is_empty() { translated_source } else { format!("(?{prefix}){translated_source}") };
        fancy_regex::Regex::new(&pattern).ok()
    }
    /// Match a string with JavaScript String.prototype.match semantics.
    pub fn match_string(&self, haystack: &str) -> Option<Vec<String>> {
        let regex = self.try_compiled()?;
        if self.has_flag('g') {
            let matches = regex.find_iter(haystack).filter_map(Result::ok).map(|value| value.as_str().to_owned()).collect::<Vec<_>>();
            if matches.is_empty() { None } else { Some(matches) }
        }
        else {
            let captures = regex.captures(haystack).ok().flatten()?;
            Some((0..captures.len()).map(|index| captures.get(index).map_or(String::new(), |value| value.as_str().to_owned())).collect::<Vec<_>>())
        }
    }
    /// Split a string with JavaScript RegExp separator semantics.
    pub fn split_string(&self, haystack: &str) -> Vec<String> {
        let Some(regex) = self.try_compiled() else { return vec![haystack.to_owned()]; };
        regex.split(haystack).filter_map(Result::ok).map(str::to_owned).collect::<Vec<_>>()
    }
    /// Replace matches with JavaScript RegExp-aware String.prototype.replace semantics.
    pub fn replace_string(&self, haystack: &str, replacement: &str, force_all: bool) -> String {
        let Some(regex) = self.try_compiled() else { return haystack.to_owned(); };
        let replace_all = force_all || self.has_flag('g');
        if replace_all {
            let mut output = String::new();
            let mut last_end = 0usize;
            for matched in regex.find_iter(haystack).filter_map(Result::ok) {
                output.push_str(&haystack[last_end..matched.start()]);
                output.push_str(replacement);
                last_end = matched.end();
            }
            output.push_str(&haystack[last_end..]);
            output
        }
        else if let Ok(Some(matched)) = regex.find(haystack) {
            format!("{}{}{}", &haystack[..matched.start()], replacement, &haystack[matched.end()..])
        } else {
            haystack.to_owned()
        }
    }
    /// Execute this RegExp and return a concrete `SmeltMatch` result.
    ///
    /// The match result is a typed `SmeltMatch` value (numbered groups,
    /// named groups, `index`, `input`) instead of an erased `SmeltUnknown`
    /// property bag; callers erase it explicitly at a dynamic boundary via
    /// `SmeltMatch::into_smelt_unknown` when required.
    pub fn exec(&self, haystack: &str) -> Option<SmeltMatch> {
        let regex = self.compiled();
        let start = if self.has_flag('g') || self.has_flag('y') { *self.last_index.borrow() } else { 0 };
        let suffix = haystack.get(start..).unwrap_or("");
        let captures = regex.captures(suffix).ok().flatten()?;
        let matched = captures.get(0)?;
        if self.has_flag('y') && matched.start() != 0 { *self.last_index.borrow_mut() = 0; return None; }
        if self.has_flag('g') || self.has_flag('y') { *self.last_index.borrow_mut() = start + matched.end(); }
        Some(SmeltMatch::from_captures(&regex, &captures, start + matched.start(), haystack))
    }
    /// Return concrete `SmeltMatch` results for String.prototype.matchAll.
    pub fn match_all_indices(&self, haystack: &str) -> Vec<SmeltMatch> {
        let Some(regex) = self.try_compiled() else { return Vec::new(); };
        regex.captures_iter(haystack).filter_map(Result::ok).filter_map(|captures| {
            let matched = captures.get(0)?;
            Some(SmeltMatch::from_captures(&regex, &captures, matched.start(), haystack))
        }
        ).collect::<Vec<_>>()
    }
    /// Test this RegExp against a string with JavaScript lastIndex updates.
    pub fn test(&self, haystack: &str) -> bool {
        self.exec(haystack).is_some()
    }
}

impl IntoSmeltUnknown for SmeltRegExp {
    fn into_smelt_unknown(self) -> SmeltUnknown {
        SmeltUnknown::Object(SmeltObject::with_id(self.id, ::std::collections::HashMap::from([
        ("source".to_owned(), SmeltUnknown::String(self.source)),
        ("flags".to_owned(), SmeltUnknown::String(self.flags)),
        ("__smelt_regexp".to_owned(), SmeltUnknown::Bool(true)),
        ])))
    }
}

impl Default for SmeltRegExp {
    /// Construct a RegExp that matches the empty string.
    fn default() -> Self {
        Self::new(String::new(), String::new())
    }
}

/// A concrete JavaScript RegExp match result (numbered groups, named
/// groups, `index`, and `input`).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct SmeltMatch {
    id: usize,
    /// Numbered capture groups; entry 0 is the whole match. An absent
    /// optional group is `None` (JavaScript `undefined`).
    groups: Vec<Option<String>>,
    /// Named capture groups keyed by name (plus a snake_case alias).
    named: ::std::collections::HashMap<String, Option<String>>,
    /// Zero-based offset of the match within `input` (`.index`).
    match_index: usize,
    /// The full string that was searched (`.input`).
    input: String,
}

#[allow(dead_code)]
impl SmeltMatch {
    /// Build a `SmeltMatch` from a compiled regex and its captures.
    fn from_captures(regex: &fancy_regex::Regex, captures: &fancy_regex::Captures<'_>, match_index: usize, input: &str) -> Self {
        let groups = (0..captures.len()).map(|index| captures.get(index).map(|value| value.as_str().to_owned())).collect::<Vec<_>>();
        let mut named = ::std::collections::HashMap::new();
        for name in regex.capture_names().flatten() {
            let value = captures.name(name).map(|value| value.as_str().to_owned());
            named.insert(name.to_owned(), value.clone());
            let mut snake = String::new();
            for (index, ch) in name.chars().enumerate() {
                if ch.is_ascii_uppercase() { if index > 0 { snake.push('_'); } snake.push(ch.to_ascii_lowercase()); } else { snake.push(ch); }
            }
            named.insert(snake, value);
        }
        Self { id: smelt_next_object_id(), groups, named, match_index, input: input.to_owned() }
    }
    /// Read a numbered capture group (`match[n]`).
    fn group(&self, index: usize) -> Option<&str> {
        self.groups.get(index).and_then(|value| value.as_deref())
    }
    /// Read a numbered capture group as an owned optional string.
    ///
    /// Consumer index reads (`match[n]`) are typed `Optional(String)`; a
    /// group that did not participate in the match is `None` (JavaScript
    /// `undefined`).
    pub fn group_owned(&self, index: usize) -> Option<String> {
        self.groups.get(index).cloned().flatten()
    }
    /// Read a named capture group (`match.groups.name`).
    fn named_group(&self, name: &str) -> Option<&str> {
        self.named.get(name).and_then(|value| value.as_deref())
    }
    /// Read a named capture group as an owned optional string.
    ///
    /// Consumer named-group reads (`match.groups.name`) are typed
    /// `Optional(String)`; a group that did not participate is `None`.
    pub fn named_group_owned(&self, name: &str) -> Option<String> {
        self.named.get(name).cloned().flatten()
    }
    /// The zero-based match offset (`match.index`).
    pub fn index(&self) -> f64 {
        self.match_index as f64
    }
    /// The full searched string (`match.input`).
    fn input(&self) -> &str {
        &self.input
    }
    /// The full searched string as an owned value (`match.input`).
    pub fn input_owned(&self) -> String {
        self.input.clone()
    }
    /// Number of numbered capture groups, including the whole match.
    fn len(&self) -> usize {
        self.groups.len()
    }
    /// Number of numbered capture groups as a JavaScript number (`match.length`).
    pub fn length(&self) -> f64 {
        self.groups.len() as f64
    }
    /// Whether there are no numbered groups (never true for a real match).
    fn is_empty(&self) -> bool {
        self.groups.is_empty()
    }
}

/// Erase a concrete match into a `SmeltUnknown` at a dynamic boundary.
///
/// This reproduces the JavaScript match-array-with-properties shape:
/// numbered string keys for the groups plus `groups`, `index`, and
/// `input`. It is the single explicit adapter used when a typed
/// `SmeltMatch` must flow into erased `unknown` consumer dataflow.
impl IntoSmeltUnknown for SmeltMatch {
    fn into_smelt_unknown(self) -> SmeltUnknown {
        let mut object = ::std::collections::HashMap::new();
        for (index, value) in self.groups.iter().enumerate() { object.insert(index.to_string(), value.clone().map_or(SmeltUnknown::Undefined, SmeltUnknown::String)); }
        let groups = self.named.into_iter().map(|(name, value)| (name, value.map_or(SmeltUnknown::Undefined, SmeltUnknown::String))).collect::<::std::collections::HashMap<_, _>>();
        object.insert("groups".to_owned(), SmeltUnknown::Object(SmeltObject::new(groups)));
        object.insert("index".to_owned(), SmeltUnknown::Number(self.match_index as f64));
        object.insert("input".to_owned(), SmeltUnknown::String(self.input));
        SmeltUnknown::Object(SmeltObject::with_id(self.id, object))
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
struct User {
    name: String,
    scores: SmeltList<f64>,
}
impl IntoSmeltUnknown for User {
    fn into_smelt_unknown(self) -> SmeltUnknown {
        SmeltUnknown::Object(SmeltObject::new(::std::collections::HashMap::from([
        ("name".to_owned(), SmeltUnknown::String(self.name)),
        ("scores".to_owned(), SmeltUnknown::Array(self.scores.into_iter().map(|value| SmeltUnknown::Number(value as f64)).collect())),
        ])))
    }
}

